def get_slab_bounds(slab):
    # This is a simplified way to find dimensions.
    # Usually, we look at the Representation.
    if slab.Representation:
        for representation in slab.Representation.Representations:
            if representation.RepresentationIdentifier == 'Body':
                for item in representation.Items:
                    if item.is_a('IfcExtrudedAreaSolid'):
                        profile = item.SweptArea
                        if profile.is_a('IfcRectangleProfileDef'):
                            return profile.XDim, profile.YDim, item.Position
    return None, None, None

