def search_recursive(obj, path="", seen=None):
    if seen is None: seen = set()
    if id(obj) in seen: return
    seen.add(id(obj))

    if isinstance(obj, (int, float, str)):
        if "height" in str(obj).lower() or "depth" in str(obj).lower() or "thickness" in str(obj).lower():
            result.append(f"{path}: {obj}")
        return

    if hasattr(obj, "is_a"):
        for i, val in enumerate(obj):
            try:
                name = obj.attribute_name(i)
                search_recursive(val, f"{path}.{name}", seen)
            except:
                pass

