# Helper to create placement
def create_ifclocalplacement(ifc, location, relative_to=None):
    location_obj = ifc.createIfcCartesianPoint(location)
    axis2placement = ifc.createIfcAxis2Placement3D(location_obj, None, None)
    return ifc.createIfcLocalPlacement(relative_to, axis2placement)

