def get_wall_length(wall):
    # Try Qto_WallBaseQuantities
    for relDefinesByProperties in wall.IsDefinedBy:
        if relDefinesByProperties.is_a('IfcRelDefinesByProperties'):
            prop_set = relDefinesByProperties.RelatingPropertyDefinition
            if prop_set.is_a('IfcElementQuantity'):
                for quantity in prop_set.Quantities:
                    if quantity.is_a('IfcQuantityLength') and 'Length' in quantity.Name:
                        return quantity.LengthValue

    # Try properties
    for relDefinesByProperties in wall.IsDefinedBy:
        if relDefinesByProperties.is_a('IfcRelDefinesByProperties'):
            prop_set = relDefinesByProperties.RelatingPropertyDefinition
            if prop_set.is_a('IfcPropertySet'):
                for prop in prop_set.HasProperties:
                    if prop.is_a('IfcPropertySingleValue') and 'Length' in prop.Name:
                        if isinstance(prop.NominalValue.wrappedValue, (int, float)):
                            return prop.NominalValue.wrappedValue

    # If no property, try to estimate from representation axis
    if wall.Representation:
        for rep in wall.Representation.Representations:
            if rep.RepresentationIdentifier == 'Axis':
                # This is a bit complex to parse manually without geom, 
                # but let's see if we can get a simple distance if it's a line
                for item in rep.Items:
                    if item.is_a('IfcPolyline'):
                        pts = item.Points
                        if len(pts) >= 2:
                            p1 = pts[0].Coordinates
                            p2 = pts[-1].Coordinates
                            return ((p2[0]-p1[0])**2 + (p2[1]-p1[1])**2)**0.5
    return 0

