def is_parallel(dir1, dir2, tolerance=1e-5):
    if not dir1 or not dir2: return False
    # Simplified for 2D/3D direction ratios
    # Normalize
    def norm(d):
        l = math.sqrt(sum(x*x for x in d))
        return [x/l for x in d]

    d1 = norm(dir1)
    d2 = norm(dir2)

    # Dot product
    dot = sum(a*b for a, b in zip(d1, d2))
    return abs(abs(dot) - 1.0) < tolerance

