    # But a simpler way is to look for the Axis representation
    points = []
    if wall.Representation:
        for rep in wall.Representation.Representations:
            if rep.RepresentationType == 'Curve2D' or rep.RepresentationIdentifier == 'Axis':
                for item in rep.Items:
                    if item.is_a('IfcPolyline'):
                        points = [p.Coordinates for p in item.Points]
                    elif item.is_a('IfcTrimmedCurve'):
                        # Handle trimmed curves if needed, but polyline is common
                        pass

    # Transform points to world coordinates using ObjectPlacement
    # For now, let's just see the local points
    return points

