def get_bbox(elem):
    try:
        shape = ifcopenshell.geom.create_shape(settings, elem)
        verts = shape.geometry.verts
        if not verts: return None
        xs = verts[0::3]
        ys = verts[1::3]
        zs = verts[2::3]
        return (min(xs), min(ys), min(zs), max(xs), max(ys), max(zs))
    except:
        return None

