import math

def get_space_center(space):
    shape = space.Representation
    if not shape: return None
    for rep in shape.Representations:
        for item in rep.Items:
            if item.is_a('IfcExtrudedAreaSolid'):
                profile = item.SweptArea
                if profile.is_a('IfcArbitraryClosedProfileDef'):
                    # This is complex, let's look for IfcRectangleProfileDef or similar
                    pass
                if profile.is_a('IfcRectangleProfileDef'):
                    # Center of rectangle
                    rect_pos = profile.Position.Location.Coordinates if profile.Position else (0,0)
                    # item.Position is the placement of the extrusion
                    extr_pos = item.Position.Location.Coordinates if item.Position else (0,0,0)
                    return (rect_pos[0] + extr_pos[0], rect_pos[1] + extr_pos[1])
                # If polyline, average the points
                if hasattr(profile, 'OuterCurve') and profile.OuterCurve.is_a('IfcPolyline'):
                    pts = profile.OuterCurve.Points
                    avg_x = sum(p.Coordinates[0] for p in pts) / len(pts)
                    avg_y = sum(p.Coordinates[1] for p in pts) / len(pts)
                    extr_pos = item.Position.Location.Coordinates if item.Position else (0,0,0)
                    return (avg_x + extr_pos[0], avg_y + extr_pos[1])
    return None

