def get_brep_center(brep):
    shell = brep.Outer
    points = []
    for face in shell.CfsFaces:
        for bound in face.Bounds:
            if bound.is_a('IfcPolyLoop'):
                for pt in bound.Polygon:
                    points.append(pt.Coordinates)
    if not points: return None
    avg_x = sum(p[0] for p in points) / len(points)
    avg_y = sum(p[1] for p in points) / len(points)
    return (avg_x, avg_y)

def get_extrusion_center(item):
    profile = item.SweptArea
    avg_x, avg_y = 0, 0
    if profile.is_a('IfcArbitraryClosedProfileDef'):
        if hasattr(profile, 'OuterCurve') and profile.OuterCurve.is_a('IfcPolyline'):
            pts = profile.OuterCurve.Points
            avg_x = sum(p.Coordinates[0] for p in pts) / len(pts)
            avg_y = sum(p.Coordinates[1] for p in pts) / len(pts)
    elif profile.is_a('IfcRectangleProfileDef'):
        avg_x = profile.Position.Location.Coordinates[0] if profile.Position else 0
        avg_y = profile.Position.Location.Coordinates[1] if profile.Position else 0

    extr_pos = item.Position.Location.Coordinates if item.Position else (0,0,0)
    return (avg_x + extr_pos[0], avg_y + extr_pos[1])

