import math

def get_dist(p1, p2):
    return math.sqrt(sum((a - b)**2 for a, b in zip(p1, p2)))

def get_polyline_length(polyline):
    points = [p.Coordinates for p in polyline.Points]
    length = 0
    for i in range(len(points) - 1):
        length += get_dist(points[i], points[i+1])
    return length

