import math

def get_perimeter(profile):
    if profile.is_a('IfcRectangleProfileDef'):
        return 2 * (profile.XDim + profile.YDim)
    elif profile.is_a('IfcCircleProfileDef'):
        return 2 * math.pi * profile.Radius
    elif profile.is_a('IfcArbitraryClosedProfileDef'):
        # For arbitrary closed profiles, we'd need to traverse the curve segments.
        # This is complex. Let's see if we have these.
        return 0.0 
    return 0.0

