import math

def get_profile_data(profile):
    perimeter = 0.0
    area = 0.0
    if profile.is_a('IfcRectangleProfileDef'):
        perimeter = 2 * (profile.XDim + profile.YDim)
        area = profile.XDim * profile.YDim
    elif profile.is_a('IfcCircleProfileDef'):
        perimeter = 2 * math.pi * profile.Radius
        area = math.pi * (profile.Radius**2)
    elif profile.is_a('IfcArbitraryClosedProfileDef'):
        # Just a placeholder, calculation would require curve analysis
        perimeter = -1.0 
        area = -1.0
    return perimeter, area

