def get_abs_pos(element):
    placement = element.ObjectPlacement
    if not placement:
        return (0, 0, 0)

    # This is a simplified version, usually we'd want the full matrix
    # But for a simple comparison, LocalPlacement.RelativePlacement.Location.Coordinates is often enough
    # if the nesting is not too complex.
    try:
        if placement.is_a('IfcLocalPlacement'):
            loc = placement.RelativePlacement.Location.Coordinates
            return loc
    except:
        return (0, 0, 0)
    return (0,0,0)

