import ifcopenshell.util.element

def get_container(element):
    while element:
        if element.is_a("IfcSpace"):
            return element
        if element.is_a("IfcBuildingStorey"):
            return element
        # Check for containment
        container = None
        for rel in element.ContainedInStructure:
            container = rel.RelatingStructure
            break
        if container:
            return container
        # Check for fill in opening
        for rel in element.FillsVoids:
            opening = rel.RelatingOpeningElement
            for rel2 in opening.VoidsElements:
                wall = rel2.RelatingBuildingElement
                # Walls are usually contained in storeys
                for rel3 in wall.ContainedInStructure:
                    return rel3.RelatingStructure
        break
    return None

